  // Vault (P-RF03)
  getIt.registerLazySingleton<VaultSecureStorage>(VaultSecureStorage.new);
  getIt.registerLazySingleton<LocalAuthBiometricDataSource>(
    LocalAuthBiometricDataSource.new,
