25	/// One screen-scoped bloc for the whole Insertion Modal
26	/// (contracts/insertion-modal-bloc.md) — created fresh by `BlocProvider`
27	/// every time `showModalBottomSheet` opens the modal, which is what makes
28	/// FR-002's "reset every tab... each time the modal is freshly opened" true
29	/// without an explicit reset event.
30	class InsertionModalBloc
31	    extends Bloc<InsertionModalEvent, InsertionModalState> {
32	  InsertionModalBloc({
33	    required this._saveTextEntryUseCase,
34	    required this._audioCaptureRepository,
35	    required this._audioTranscriptionRepository,
36	    required this._confirmEntrySaveUseCase,
37	    required this._photoCaptureRepository,
38	    required this._recognizePhotoUseCase,
39	  }) : super(const InsertionModalTexto()) {
40	    on<TabSelected>(_onTabSelected);
41	    on<TextDraftChanged>(_onTextDraftChanged);
42	    on<SaveTextSubmitted>(_onSaveTextSubmitted);
43	    on<AudioStartRequested>(_onAudioStartRequested);
44	    on<AudioTimerTicked>(_onAudioTimerTicked);
45	    on<AudioStopRequested>(_onAudioStopRequested);
46	    on<AudioReviewTextChanged>(_onAudioReviewTextChanged);
47	    on<AudioSaveConfirmed>(_onAudioSaveConfirmed);
48	    on<PhotoSourceSelected>(_onPhotoSourceSelected);
49	    on<PhotoReviewTextChanged>(_onPhotoReviewTextChanged);
50	    on<PhotoSaveConfirmed>(_onPhotoSaveConfirmed);
51	    on<PhotoSaveWithoutTextRequested>(_onPhotoSaveWithoutTextRequested);
52	    on<RetryRequested>(_onRetryRequested);
53	    on<ModalClosed>(_onModalClosed);
54	  }
55	
56	  final SaveTextEntryUseCase _saveTextEntryUseCase;
57	  final AudioCaptureRepository _audioCaptureRepository;
58	  final AudioTranscriptionRepository _audioTranscriptionRepository;
59	  final ConfirmEntrySaveUseCase _confirmEntrySaveUseCase;
60	  final PhotoCaptureRepository _photoCaptureRepository;
61	  final RecognizePhotoUseCase _recognizePhotoUseCase;
62	
63	  final _closeController = StreamController<void>.broadcast();
64	
65	  /// A one-shot side effect, not a state (FR-011, contracts/
66	  /// insertion-modal-bloc.md) — `InsertionModalPage` listens to this to pop
67	  /// the sheet. There is nothing to render for "success", so it never
68	  /// becomes a dedicated `InsertionModalState` case.
69	  Stream<void> get closeRequests => _closeController.stream;
70	
71	  String _textDraft = '';
72	  String? _pendingAudioPath;
73	  String? _pendingImagePath;
74	
75	  /// The editable review field's current draft while Transcrito/Reconhecido
76	  /// (or their respective SaveFailure), seeded from the recognition result
77	  /// (data-model.md's Recognition Attempt).
78	  String? _audioReviewText;
79	  String? _photoReviewText;
80	  Timer? _audioTicker;
81	
82	  /// Guards against discarding the same recording twice when both the
83	  /// explicit `ModalClosed` handler and `close()`'s disposal-time fallback
84	  /// (for the swipe-down/tap-outside dismissal that bypasses `ModalClosed`)
85	  /// would otherwise race on the same still-recording state.
86	  bool _recordingDiscarded = false;
87	
88	  bool _isAudioAbandonable(InsertionModalState state) =>
89	      state is InsertionModalAudioProcessing ||
90	      state is InsertionModalAudioTranscribed ||
91	      state is InsertionModalAudioSaving ||
92	      state is InsertionModalAudioSaveFailure ||
93	      state is InsertionModalAudioFailure;
94	
95	  bool _isFotoAbandonable(InsertionModalState state) =>
96	      state is InsertionModalFotoProcessing ||
97	      state is InsertionModalFotoReconhecido ||
98	      state is InsertionModalFotoSaving ||
99	      state is InsertionModalFotoSaveFailure ||
100	      state is InsertionModalFotoFailure;
101	
102	  Future<void> _onTabSelected(
103	    TabSelected event,
104	    Emitter<InsertionModalState> emit,
105	  ) async {
106	    final current = state;
107	    if (current is InsertionModalAudioRecording) {
108	      // Switching away mid-recording discards it (Edge Cases) — nothing
109	      // from an abandoned capture may survive (FR-011).
110	      _audioCaptureRepository.discard();
111	      _recordingDiscarded = true;
112	      _stopAudioTicker();
113	      _pendingAudioPath = null;
114	    } else if (_isAudioAbandonable(current)) {
115	      // Leaving any in-flight/reviewed/failed Áudio sub-state abandons the
116	      // held audio and any unsaved review edits (FR-011, data-model.md's
117	      // transition table).
118	      _pendingAudioPath = null;
119	      _audioReviewText = null;
120	    }
121	
122	    if (_isFotoAbandonable(current)) {
123	      _pendingImagePath = null;
124	      _photoReviewText = null;
125	    }
126	
127	    switch (event.tab) {
128	      case CaptureTab.texto:
129	        emit(InsertionModalTexto(text: _textDraft));
130	      case CaptureTab.audio:
131	        emit(const InsertionModalAudioIdle());
132	      case CaptureTab.foto:
133	        emit(const InsertionModalFotoCaptura());
134	    }
135	  }
136	
137	  Future<void> _onAudioStartRequested(
138	    AudioStartRequested event,
139	    Emitter<InsertionModalState> emit,
140	  ) async {
141	    if (state is! InsertionModalAudioIdle) return;
142	
143	    final hasPermission = await _audioCaptureRepository.hasPermission();
144	    if (!hasPermission) {
145	      emit(const InsertionModalAudioPermissionDenied());
146	      return;
147	    }
148	    await _audioCaptureRepository.start();
149	    _recordingDiscarded = false;
150	    emit(const InsertionModalAudioRecording(elapsed: Duration.zero));
151	    _startAudioTicker();
152	  }
153	
154	  void _startAudioTicker() {
155	    _audioTicker?.cancel();
156	    _audioTicker = Timer.periodic(
157	      const Duration(seconds: 1),
158	      (_) => add(const AudioTimerTicked()),
159	    );
160	  }
161	
162	  void _stopAudioTicker() {
163	    _audioTicker?.cancel();
164	    _audioTicker = null;
165	  }
166	
167	  void _onTextDraftChanged(
168	    TextDraftChanged event,
169	    Emitter<InsertionModalState> emit,
170	  ) {
171	    _textDraft = event.text;
172	    emit(InsertionModalTexto(text: event.text));
173	  }
174	
175	  void _onAudioTimerTicked(
176	    AudioTimerTicked event,
177	    Emitter<InsertionModalState> emit,
178	  ) {
179	    final current = state;
180	    if (current is InsertionModalAudioRecording) {
181	      emit(
182	        InsertionModalAudioRecording(
183	          elapsed: current.elapsed + const Duration(seconds: 1),
184	        ),
185	      );
186	    }
187	  }
188	
189	  Future<void> _onSaveTextSubmitted(
190	    SaveTextSubmitted event,
191	    Emitter<InsertionModalState> emit,
192	  ) async {
193	    final current = state;
194	    final text = switch (current) {
195	      InsertionModalTexto(text: final t) => t,
196	      InsertionModalTextoFailure(text: final t) => t,
197	      _ => null,
198	    };
199	    if (text == null || text.trim().isEmpty) return;
200	
201	    emit(InsertionModalTextoSaving(text));
202	    final result = await _saveTextEntryUseCase(text);
203	    result.match(
204	      (failure) => emit(
205	        InsertionModalTextoFailure(text: text, message: failure.message),
206	      ),
207	      (entry) => _completeSave(),
208	    );
209	  }
210	
211	  Future<void> _onAudioStopRequested(
212	    AudioStopRequested event,
213	    Emitter<InsertionModalState> emit,
214	  ) async {
215	    final current = state;
216	    if (current is! InsertionModalAudioRecording) return;
217	
218	    _stopAudioTicker();
219	    final duration = current.elapsed;
220	    final path = await _audioCaptureRepository.stop();
221	    _pendingAudioPath = path;
222	    // No connectivity gate (FR-001, research.md R1) — on-device
223	    // transcription must begin unconditionally on stop.
224	    emit(InsertionModalAudioProcessing(duration: duration));
225	    await _transcribeAudio(path, duration, emit);
226	  }
227	
228	  Future<void> _transcribeAudio(
229	    String audioFilePath,
230	    Duration duration,
231	    Emitter<InsertionModalState> emit,
232	  ) async {
233	    final result = await _audioTranscriptionRepository.transcribe(
234	      audioFilePath,
235	    );
236	
237	    // The user may have switched tabs/closed the modal while transcription
238	    // was running — discard a stale result outright (research.md R6,
239	    // FR-011/User Story 5).
240	    if (state is! InsertionModalAudioProcessing ||
241	        _pendingAudioPath != audioFilePath) {
242	      return;
243	    }
244	
245	    result.match(
246	      (failure) => emit(
247	        InsertionModalAudioFailure(
248	          duration: duration,
249	          message: _recognitionFailureMessage(failure),
250	        ),
251	      ),
252	      (text) {
253	        _audioReviewText = text;
254	        emit(InsertionModalAudioTranscribed(text: text, duration: duration));
255	      },
256	    );
257	  }
258	
259	  String _recognitionFailureMessage(RecognitionFailure failure) =>
260	      switch (failure) {
261	        EmptyRecognitionResult() => _noSpeechMessage,
262	        TranscriptionError() => _genericAudioMessage,
263	      };
264	
265	  void _onAudioReviewTextChanged(
266	    AudioReviewTextChanged event,
267	    Emitter<InsertionModalState> emit,
268	  ) {
269	    final current = state;
270	    if (current is InsertionModalAudioTranscribed) {
271	      _audioReviewText = event.text;
272	      emit(
273	        InsertionModalAudioTranscribed(
274	          text: event.text,
275	          duration: current.duration,
276	        ),
277	      );
278	    } else if (current is InsertionModalAudioSaveFailure) {
279	      _audioReviewText = event.text;
280	      emit(
281	        InsertionModalAudioSaveFailure(
282	          text: event.text,
283	          duration: current.duration,
284	          message: current.message,
285	        ),
286	      );
287	    }
288	  }
289	
290	  Future<void> _onAudioSaveConfirmed(
291	    AudioSaveConfirmed event,
292	    Emitter<InsertionModalState> emit,
293	  ) async {
294	    final current = state;
295	    final duration = switch (current) {
296	      InsertionModalAudioTranscribed(duration: final d) => d,
297	      InsertionModalAudioSaveFailure(duration: final d) => d,
298	      _ => null,
299	    };
300	    if (duration == null) return;
301	
302	    final text = _audioReviewText;
303	    if (text == null || text.trim().isEmpty) return;
304	
305	    emit(InsertionModalAudioSaving(text: text, duration: duration));
306	    final result = await _confirmEntrySaveUseCase(text, EntrySource.audio);
307	    result.match(
308	      (failure) => emit(
309	        InsertionModalAudioSaveFailure(
310	          text: text,
311	          duration: duration,
312	          message: _confirmSaveFailureMessage(failure),
313	        ),
314	      ),
315	      (entry) {
316	        _pendingAudioPath = null;
317	        _audioReviewText = null;
318	        _completeSave();
319	      },
320	    );
321	  }
322	
323	  Future<void> _onPhotoSourceSelected(
324	    PhotoSourceSelected event,
325	    Emitter<InsertionModalState> emit,
326	  ) async {
327	    final current = state;
328	    if (current is InsertionModalFotoProcessing ||
329	        current is InsertionModalFotoSaving) {
330	      return;
331	    }
332	
333	    String? path;
334	    try {
335	      path = await _photoCaptureRepository.pickImage(event.source);
336	    } catch (_) {
337	      emit(const InsertionModalFotoPermissionDenied());
338	      return;
339	    }
340	
341	    if (path == null) {
342	      emit(const InsertionModalFotoCaptura());
343	      return;
344	    }
345	
346	    _pendingImagePath = path;
347	    emit(InsertionModalFotoProcessing(imagePath: path));
348	    await _recognizePhoto(path, emit);
349	  }
350	
351	  Future<void> _recognizePhoto(
352	    String imageFilePath,
353	    Emitter<InsertionModalState> emit,
354	  ) async {
355	    final result = await _recognizePhotoUseCase(imageFilePath);
356	
357	    // Same stale-result guard as audio (research.md R6).
358	    if (state is! InsertionModalFotoProcessing ||
359	        _pendingImagePath != imageFilePath) {
360	      return;
361	    }
362	
363	    result.match(
364	      (failure) => emit(
365	        InsertionModalFotoFailure(
366	          imagePath: imageFilePath,
367	          message: _photoRecognitionFailureMessage(failure),
368	        ),
369	      ),
370	      (ocrResult) {
371	        // confidence read but never branched on (Clarification 3).
372	        _photoReviewText = ocrResult.text;
373	        emit(
374	          InsertionModalFotoReconhecido(
375	            imagePath: imageFilePath,
376	            text: ocrResult.text,
377	          ),
378	        );
379	      },
380	    );
381	  }
382	
383	  String _photoRecognitionFailureMessage(
384	    PhotoRecognitionAttemptFailure failure,
385	  ) => switch (failure) {
386	    PhotoRecognitionOffline() => _offlineMessage,
387	    PhotoRecognitionCallFailed(failure: final f) =>
388	      f is OcrNoTextFailure ? _noTextMessage : f.message,
389	  };
390	
391	  void _onPhotoReviewTextChanged(
392	    PhotoReviewTextChanged event,
393	    Emitter<InsertionModalState> emit,
394	  ) {
395	    final current = state;
396	    if (current is InsertionModalFotoReconhecido) {
397	      _photoReviewText = event.text;
398	      emit(
399	        InsertionModalFotoReconhecido(
400	          imagePath: current.imagePath,
401	          text: event.text,
402	        ),
403	      );
404	    } else if (current is InsertionModalFotoSaveFailure) {
405	      _photoReviewText = event.text;
406	      emit(
407	        InsertionModalFotoSaveFailure(
408	          imagePath: current.imagePath,
409	          text: event.text,
410	          message: current.message,
411	        ),
412	      );
413	    }
414	  }
415	
416	  Future<void> _onPhotoSaveConfirmed(
417	    PhotoSaveConfirmed event,
418	    Emitter<InsertionModalState> emit,
419	  ) async {
420	    final current = state;
421	    final imagePath = switch (current) {
422	      InsertionModalFotoReconhecido(imagePath: final p) => p,
423	      InsertionModalFotoSaveFailure(imagePath: final p) => p,
424	      _ => null,
425	    };
426	    if (imagePath == null) return;
427	
428	    final text = _photoReviewText;
429	    if (text == null || text.trim().isEmpty) return;
430	
431	    await _confirmPhotoSave(imagePath, text, emit);
432	  }
433	
434	  Future<void> _onPhotoSaveWithoutTextRequested(
435	    PhotoSaveWithoutTextRequested event,
436	    Emitter<InsertionModalState> emit,
437	  ) async {
438	    final current = state;
439	    if (current is! InsertionModalFotoFailure) return;
440	
441	    // No further OCR call for this capture (FR-008) — saves immediately
442	    // with the fixed placeholder.
443	    await _confirmPhotoSave(current.imagePath, _photoNoTextPlaceholder, emit);
444	  }
445	
446	  Future<void> _confirmPhotoSave(
447	    String imagePath,
448	    String text,
449	    Emitter<InsertionModalState> emit,
450	  ) async {
451	    emit(InsertionModalFotoSaving(imagePath: imagePath, text: text));
452	    final result = await _confirmEntrySaveUseCase(text, EntrySource.photo);
453	    result.match(
454	      (failure) => emit(
455	        InsertionModalFotoSaveFailure(
456	          imagePath: imagePath,
457	          text: text,
458	          message: _confirmSaveFailureMessage(failure),
459	        ),
460	      ),
461	      (entry) {
462	        _pendingImagePath = null;
463	        _photoReviewText = null;
464	        _completeSave();
465	      },
466	    );
467	  }
468	
469	  String _confirmSaveFailureMessage(ConfirmEntrySaveFailure failure) =>
470	      switch (failure) {
471	        ConfirmEntrySaveOffline() => _offlineMessage,
472	        ConfirmEntrySaveCreationFailed(failure: final f) => f.message,
473	      };
474	
475	  Future<void> _onRetryRequested(
476	    RetryRequested event,
477	    Emitter<InsertionModalState> emit,
478	  ) async {
479	    final current = state;
480	    final audioPath = _pendingAudioPath;
481	    final imagePath = _pendingImagePath;
482	    if (current is InsertionModalAudioFailure && audioPath != null) {
483	      final duration = current.duration;
484	      emit(InsertionModalAudioProcessing(duration: duration));
485	      await _transcribeAudio(audioPath, duration, emit);
486	    } else if (current is InsertionModalFotoFailure && imagePath != null) {
487	      emit(InsertionModalFotoProcessing(imagePath: imagePath));
488	      await _recognizePhoto(imagePath, emit);
489	    }
490	  }
491	
492	  void _onModalClosed(ModalClosed event, Emitter<InsertionModalState> emit) {
493	    if (state is InsertionModalAudioRecording) {
494	      _audioCaptureRepository.discard();
495	      _recordingDiscarded = true;
496	      _stopAudioTicker();
497	    }
498	    // Unconditionally clears every held capture/review, regardless of
499	    // which Áudio/Foto sub-state is active when the modal closes (FR-011).
500	    _pendingAudioPath = null;
501	    _audioReviewText = null;
502	    _pendingImagePath = null;
503	    _photoReviewText = null;
504	  }
505	
506	  void _completeSave() {
507	    if (!_closeController.isClosed) {
508	      _closeController.add(null);
509	    }
510	  }
511	
512	  @override
513	  Future<void> close() {
514	    if (state is InsertionModalAudioRecording && !_recordingDiscarded) {
515	      // `showModalBottomSheet`'s default swipe-down/tap-outside dismissal
516	      // bypasses `ModalClosed` entirely, so this is the only place that
517	      // reliably catches a still-recording mic at disposal time (FR-011).
518	      _audioCaptureRepository.discard();
519	      _recordingDiscarded = true;
520	      _pendingAudioPath = null;
521	    }
522	    _stopAudioTicker();
523	    unawaited(_closeController.close());
524	    return super.close();
525	  }
526	}
